INSERT OR IGNORE INTO questions
  (id, track_id, topic, difficulty, question_type, prompt, options_json, answer_json, explanation, source_type, source_reference, language)
VALUES
('sg-official-2026-01','exam-sg','リスクマネジメント','standard','single_choice','【2026年度 IPA公開問題 問1】情報セキュリティのリスクマネジメントにおける残留リスクに関する記述のうち、適切なものはどれか。','[{"id":"a","text":"経営者の意思決定に従って保有したリスクは、残留リスクに含まれない。"},{"id":"b","text":"特定されていないリスクは、残留リスクに含まれない。"},{"id":"c","text":"リスク対応を行った後に残るリスクは、残留リスクである。"},{"id":"d","text":"リスクを生じさせる活動を継続しないという決定によって回避したリスクは、残留リスクである。"}]','"c"','残留リスクは、リスク対応を実施した後にも残るリスク。対応を受容したかどうかにかかわらず、対応後に残るものを指す。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/sg_fe/koukai/rcu1hd0000012qj6-att/2026r08_sg_qs.pdf','ja'),
('sg-official-2026-02','exam-sg','インシデント対応','standard','single_choice','【2026年度 IPA公開問題 問2】組織的なインシデント対応体制の構築を支援する目的でJPCERTコーディネーションセンターが作成したものはどれか。','[{"id":"a","text":"CSIRT マテリアル"},{"id":"b","text":"ISMS ユーザーズガイド"},{"id":"c","text":"証拠保全ガイドライン"},{"id":"d","text":"組織における内部不正防止ガイドライン"}]','"a"','CSIRT マテリアルは、組織内のインシデント対応チームの構築・運用を支援する資料。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/sg_fe/koukai/rcu1hd0000012qj6-att/2026r08_sg_qs.pdf','ja'),
('sg-official-2026-03','exam-sg','ネットワークセキュリティ','standard','single_choice','【2026年度 IPA公開問題 問3】DMZはどれか。','[{"id":"a","text":"インターネットと内部ネットワークとの間に設置されるネットワーク"},{"id":"b","text":"社内ネットワークに接続する前に持込みPCのマルウェア感染を確認するため、社内ネットワークから隔離した専用ネットワーク"},{"id":"c","text":"通信を監視し、設定された不正通信パターンを検知すると遮断するネットワーク"},{"id":"d","text":"不正通信の検知に使うため、セキュリティベンダーから入手するシグネチャ情報"}]','"a"','DMZは外部公開サーバなどを配置し、インターネットと内部ネットワークの間に設ける隔離されたネットワーク領域。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/sg_fe/koukai/rcu1hd0000012qj6-att/2026r08_sg_qs.pdf','ja'),
('sg-official-2026-04','exam-sg','認証技術','standard','single_choice','【2026年度 IPA公開問題 問4】チャレンジレスポンス認証方式に該当するものはどれか。','[{"id":"a","text":"固定パスワードをTLSによる暗号通信でクライアントからサーバに送信し、サーバで検証する。"},{"id":"b","text":"端末のシリアル番号をクライアントで秘密鍵を使って暗号化し、サーバに送信して検証する。"},{"id":"c","text":"トークンが表示する認証のたびに異なる数字列をパスワードとしてサーバに送信し、サーバで検証する。"},{"id":"d","text":"利用者のパスワードとサーバから受け取ったランダムデータをクライアントで演算し、その結果をサーバに送信して検証する。"}]','"d"','サーバが毎回異なるチャレンジ値を送り、クライアントが秘密情報と組み合わせて応答を計算する方式がチャレンジレスポンス認証。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/sg_fe/koukai/rcu1hd0000012qj6-att/2026r08_sg_qs.pdf','ja'),
('sg-official-2026-05','exam-sg','脆弱性診断','standard','single_choice','【2026年度 IPA公開問題 問5】情報セキュリティでの脆弱性の検出に用いられるホワイトボックステストに該当するものはどれか。','[{"id":"a","text":"外部仕様を基に問題を引き起こしそうなデータを大量に送り、応答や挙動を監視する。"},{"id":"b","text":"ネットワーク構成図などを得ず、TCP/IPの既知の脆弱性を攻撃して侵入できるか確認する。"},{"id":"c","text":"プログラムの内部構造及び内部仕様を基に、脆弱性の可能性がある箇所の入力値を変化させて実行する。"},{"id":"d","text":"内部仕様を参照せず、変数領域のあふれを見つけるツールを利用する。"}]','"c"','ホワイトボックステストは内部構造や仕様を把握した上で検査する。外部から振る舞いを見るブラックボックステストと区別する。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/sg_fe/koukai/rcu1hd0000012qj6-att/2026r08_sg_qs.pdf','ja'),
('sg-official-2026-06','exam-sg','アクセス制御','standard','single_choice','【2026年度 IPA公開問題 問6】セキュアOSのアクセス制御と管理者権限管理を説明した適切な組合せはどれか。','[{"id":"a","text":"アクセス権はOS管理者が定めたセキュリティポリシーで一元制御し所有者は変更できない。管理は分野ごとに別アカウントを作り必要最小限の特権を与える。"},{"id":"b","text":"アクセス権はOS管理者のポリシーで一元制御する。管理用の特権アカウントに全ての権限を与える。"},{"id":"c","text":"アクセス権はリソース所有者が制御する。管理は分野ごとに別アカウントを作り必要最小限の特権を与える。"},{"id":"d","text":"アクセス権はリソース所有者が制御する。管理用の特権アカウントに全ての権限を与える。"}]','"a"','セキュアOSはポリシーに基づく集中制御を行い、管理者権限も役割ごとに分離して最小権限にする。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/sg_fe/koukai/rcu1hd0000012qj6-att/2026r08_sg_qs.pdf','ja'),
('sg-official-2026-07','exam-sg','法令','standard','single_choice','【2026年度 IPA公開問題 問7】刑法の電子計算機損壊等業務妨害に該当する行為はどれか。','[{"id":"a","text":"自社Webサイトで海賊版ソフトウェアを故意に販売する。"},{"id":"b","text":"存在しない商品をオークションサイトに出品し、落札者から金銭をだまし取る。"},{"id":"c","text":"他人の著作物を許可なく引用元も記載せず営業用Webサイトに掲載する。"},{"id":"d","text":"プロバイダのサーバに侵入し、企業が業務に使うWebページを故意に消去又は改変する。"}]','"d"','業務用Webページを故意に消去・改変して業務を妨害する行為は、電子計算機損壊等業務妨害に該当し得る。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/sg_fe/koukai/rcu1hd0000012qj6-att/2026r08_sg_qs.pdf','ja'),
('sg-official-2026-08','exam-sg','システム監査','standard','single_choice','【2026年度 IPA公開問題 問8】システム監査におけるフォローアップの説明として、適切なものはどれか。','[{"id":"a","text":"監査の品質管理体制を事前に確かめておくこと"},{"id":"b","text":"監査報告書の指摘事項に基づき、監査対象先が実施した改善措置を監査人が確認すること"},{"id":"c","text":"監査対象範囲に関する事項を文書化すること"},{"id":"d","text":"監査報告書を依頼者及び関係者に提出すること"}]','"b"','フォローアップは、監査で指摘した事項について改善措置が実施されたか、その効果があるかを確認する活動。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/sg_fe/koukai/rcu1hd0000012qj6-att/2026r08_sg_qs.pdf','ja'),
('sg-official-2026-09','exam-sg','サービスマネジメント','standard','single_choice','【2026年度 IPA公開問題 問9】サービスマネジメントにおけるサービスレベル目標の説明はどれか。','[{"id":"a","text":"意図した結果を達成するために知識及び技能を適用する能力"},{"id":"b","text":"組織が約束する、具体的に測定可能なサービスの特性"},{"id":"c","text":"トップマネジメントによって正式に表明された組織の意図及び方向付け"},{"id":"d","text":"明示又は暗黙に了解されているか、義務として要求されるニーズ又は期待"}]','"b"','サービスレベル目標は、可用性や応答時間など、サービスについて測定可能な達成目標を定めたもの。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/sg_fe/koukai/rcu1hd0000012qj6-att/2026r08_sg_qs.pdf','ja'),
('sg-official-2026-10','exam-sg','ネットワーク','standard','single_choice','【2026年度 IPA公開問題 問10】IPアドレス10.170.70.19、サブネットマスク255.255.255.240をもつPCのネットワークアドレスとして適切なものはどれか。','[{"id":"a","text":"10.170.70.0"},{"id":"b","text":"10.170.70.16"},{"id":"c","text":"10.170.70.31"},{"id":"d","text":"10.170.70.255"}]','"b"','255.255.255.240は/28で、最後のオクテットは16個単位のサブネットに分かれる。19は16〜31の範囲なのでネットワークアドレスは16。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/sg_fe/koukai/rcu1hd0000012qj6-att/2026r08_sg_qs.pdf','ja'),
('sg-official-2026-11','exam-sg','データ分析','standard','single_choice','【2026年度 IPA公開問題 問11】EC運営会社がビッグデータを収集して新たなニーズを発掘する。フローの「データの分析」で行うことはどれか。','[{"id":"a","text":"機械学習を用いて自然言語処理やクラスタリングを行い、新しい傾向を導き出す。"},{"id":"b","text":"製品に関するSNS評価などを自動プログラムで取得する。"},{"id":"c","text":"ノイズ除去やデータクレンジングを行う。"},{"id":"d","text":"発見した傾向を見極め、注力するビジネス戦略を立案する。"}]','"a"','収集はデータ取得、整備はクレンジング、分析は機械学習などによる傾向抽出、活用は戦略への反映に対応する。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/sg_fe/koukai/rcu1hd0000012qj6-att/2026r08_sg_qs.pdf','ja'),
('sg-official-2026-12','exam-sg','品質管理','standard','single_choice','【2026年度 IPA公開問題 問12】良品率0.9、不良品率0.1の外注部品について、良品・不良品1個当たりの費用が異なる4案A～Dがある。期待費用が最も低い案はどれか。A:良品0円・不良品1,500円、B:40円・1,000円、C:80円・500円、D:120円・200円。','[{"id":"a","text":"A"},{"id":"b","text":"B"},{"id":"c","text":"C"},{"id":"d","text":"D"}]','"c"','期待費用はA=150円、B=136円、C=122円、D=128円。最も低いのは案C。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/sg_fe/koukai/rcu1hd0000012qj6-att/2026r08_sg_qs.pdf','ja'),
('sg-official-2026-13','exam-sg','物理セキュリティ','standard','single_choice','【2026年度 IPA公開問題 問13】来訪者用QR入館証の使い回しと、来訪先以外の階への移動を防ぐため、ビル管理会社へ依頼する対策の組合せはどれか。','[{"id":"a","text":"QR誤り訂正レベルを高くする／入館証を1回限り有効にする"},{"id":"b","text":"QR誤り訂正レベルを高くする／平日日中も行先階でICカード認証を必須にする"},{"id":"c","text":"入館証を1回限り有効にする／QR誤り訂正レベルを高くする"},{"id":"d","text":"入館証を1回限り有効にする／平日日中も行先階でICカード認証を必須にする"},{"id":"e","text":"入館証を1回限り有効にする／ゲート脇に警備員を配置する"},{"id":"f","text":"平日日中も行先階でICカード認証を必須にする／QR誤り訂正レベルを高くする"},{"id":"g","text":"平日日中も行先階でICカード認証を必須にする／入館証を1回限り有効にする"},{"id":"h","text":"平日日中も行先階でICカード認証を必須にする／ゲート脇に警備員を配置する"},{"id":"i","text":"ゲート脇に警備員を配置する／QR誤り訂正レベルを高くする"},{"id":"j","text":"ゲート脇に警備員を配置する／入館証を1回限り有効にする"}]','"h"','使用済みQRの再利用には1回限りの入館設定が有効。入居先以外の階への移動には、平日日中も行先階でカード認証を要求する対策が適切。公式解答はク。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/sg_fe/koukai/rcu1hd0000012qj6-att/2026r08_sg_qs.pdf','ja'),
('sg-official-2026-14','exam-sg','バックアップ・事業継続','standard','single_choice','【2026年度 IPA公開問題 問14】フルバックアップは土曜2時、増分バックアップは火曜・木曜2時に実施する。RPOは72時間、RTOは120時間で、フル復元に4時間、増分復元に0.25時間かかる。監査回答の空欄（復元すべき時点／木曜正午に全損した場合の復元時間／計画書承認者）の組合せはどれか。','[{"id":"a","text":"月曜正午／4.25時間／CISO"},{"id":"b","text":"月曜正午／4.25時間／情報システム部担当者"},{"id":"c","text":"月曜正午／4.25時間／内部監査室長"},{"id":"d","text":"月曜正午／4.50時間／CISO"},{"id":"e","text":"月曜正午／4.50時間／情報システム部担当者"},{"id":"f","text":"火曜正午／4.25時間／情報システム部担当者"},{"id":"g","text":"火曜正午／4.25時間／内部監査室長"},{"id":"h","text":"火曜正午／4.50時間／CISO"},{"id":"i","text":"火曜正午／4.50時間／情報システム部担当者"},{"id":"j","text":"火曜正午／4.50時間／内部監査室長"}]','"h"','RPO 72時間から金曜正午の障害時は少なくとも火曜正午のデータが必要。木曜正午の全損では土曜フル＋火曜増分＋木曜増分の復元を想定し、4.5時間。計画書は責任者であるCISOが承認する。公式解答はク。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/sg_fe/koukai/rcu1hd0000012qj6-att/2026r08_sg_qs.pdf','ja'),
('sg-official-2026-15','exam-sg','情報資産管理','standard','single_choice','【2026年度 IPA公開問題 問15】文書管理ルールでは「極秘」「関係者外秘」「社外秘」の文書を適切に表示・保管・廃棄する。次の事例のうち、(2)営業部限定の関係者外秘議事メモ、(3)元人事部社員が人事部限定の採用計画を閲覧、(4)極秘の経営企画書最終原稿を机上に置いたまま離席、の評価（順に〇/×）の組合せはどれか。','[{"id":"a","text":"〇、〇、〇"},{"id":"b","text":"〇、〇、×"},{"id":"c","text":"〇、×、〇"},{"id":"d","text":"〇、×、×"},{"id":"e","text":"×、〇、〇"},{"id":"f","text":"×、〇、×"},{"id":"g","text":"×、×、〇"},{"id":"h","text":"×、×、×"}]','"d"','(2)は指定範囲だけが解錠できる保管庫に置き不要時に細断するため適合。 (3)は別部署の元社員に開示範囲外の採用計画を見せており不適合。(4)は極秘文書を机上に放置して離席しており不適合。公式解答はエ。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/sg_fe/koukai/rcu1hd0000012qj6-att/2026r08_sg_qs.pdf','ja');
